const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/time_and_material_notifications',
  qs: {run_configurable_validations: 'SOME_BOOLEAN_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    time_and_material_notification: {
      creation: [95861],
      customer_signed: [95861],
      company_signed: [95861],
      closed: [95861],
      group_equipment_totals_by: 'per_ticket',
      notify_dl_on_customer_signed: true,
      notify_dl_on_company_signed: true,
      notify_dl_on_creation: true,
      notify_dl_on_closed: true,
      group_labor_totals_by: 'per_ticket'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/time_and_material_notifications?run_configurable_validations=SOME_BOOLEAN_VALUE"),
    Content = new StringContent("{\"time_and_material_notification\":{\"creation\":[95861],\"customer_signed\":[95861],\"company_signed\":[95861],\"closed\":[95861],\"group_equipment_totals_by\":\"per_ticket\",\"notify_dl_on_customer_signed\":true,\"notify_dl_on_company_signed\":true,\"notify_dl_on_creation\":true,\"notify_dl_on_closed\":true,\"group_labor_totals_by\":\"per_ticket\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

